SELECT p.id AS position_id, 'ENTRY' AS role, s.id AS signal_id, s.symbol, s.interval_code, TIMESTAMPADD(MICROSECOND, CAST(ROUND(UNIX_TIMESTAMP(s.candle_open_time)*1000000) AS SIGNED), '1970-01-01 00:00:00') AS candle_open_utc, TIMESTAMPADD(MICROSECOND, CAST(ROUND(UNIX_TIMESTAMP(s.generated_at)*1000000) AS SIGNED), '1970-01-01 00:00:00') AS generated_utc, ROUND(UNIX_TIMESTAMP(s.generated_at)-UNIX_TIMESTAMP(s.candle_open_time),3) AS gen_minus_open_s, s.decision, s.original_decision, s.final_entry_allowed, s.primary_blocking_stage, s.strategy_entry_allowed, s.market_regime, s.btc_context_status, s.btc_context_entry_allowed, s.confluence_status, s.confluence_higher_decision, s.data_quality_valid, s.latest_price, s.stop_loss, s.take_profit, s.risk_reward_ratio FROM paper_position p JOIN trade_signal s ON s.id = p.signal_id WHERE p.id IN (182,172,162,158,143,137)
UNION ALL
SELECT p.id, 'EXIT', s.id, s.symbol, s.interval_code, TIMESTAMPADD(MICROSECOND, CAST(ROUND(UNIX_TIMESTAMP(s.candle_open_time)*1000000) AS SIGNED), '1970-01-01 00:00:00'), TIMESTAMPADD(MICROSECOND, CAST(ROUND(UNIX_TIMESTAMP(s.generated_at)*1000000) AS SIGNED), '1970-01-01 00:00:00'), ROUND(UNIX_TIMESTAMP(s.generated_at)-UNIX_TIMESTAMP(s.candle_open_time),3), s.decision, s.original_decision, s.final_entry_allowed, s.primary_blocking_stage, s.strategy_entry_allowed, s.market_regime, s.btc_context_status, s.btc_context_entry_allowed, s.confluence_status, s.confluence_higher_decision, s.data_quality_valid, s.latest_price, s.stop_loss, s.take_profit, s.risk_reward_ratio FROM paper_position p JOIN trade_signal s ON s.id = p.exit_signal_id WHERE p.id IN (182,172,162,158,143,137) ORDER BY 1, 2;